// Copies the brand files the site needs to serve as static assets out of the
// repository's single `assets/` directory into `site/public/`.
//
// Why a script rather than committed copies: `assets/` is the one source of
// truth for the mark, and a second committed copy under `site/` would be free
// to drift. Astro's `publicDir` cannot point at two directories, and Starlight's
// `favicon` option resolves against `publicDir`, so the file has to physically
// be there. The destinations are git-ignored and regenerated by `predev`,
// `prebuild`, and `prepreview`, so the copy only ever exists as build output.
//
// The logo itself is NOT handled here: it is imported directly from `../assets`
// by `astro.config.mjs` and processed by Vite, which needs no copy at all.

import { copyFile, mkdir } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const siteRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const assets = resolve(siteRoot, '..', 'assets');
const publicDir = join(siteRoot, 'public');

// The PWA icons are here for the same reason as the favicons: a manifest and an
// `apple-touch-icon` are fetched by URL, so the bytes have to sit under
// `publicDir`. They are rasterised from `assets/logo.svg` by
// `scripts/generate-icons.mjs`, which runs by hand when the mark changes — not
// as part of the build, which only ever copies.
const files = [
  'favicon.svg',
  'favicon-32.png',
  'icon-192.png',
  'icon-512.png',
  'icon-maskable-512.png',
  'apple-touch-icon-180.png',
];

await mkdir(publicDir, { recursive: true });
await Promise.all(files.map((file) => copyFile(join(assets, file), join(publicDir, file))));

console.log(`sync-brand: copied ${files.length} brand files from assets/ to site/public/`);
